/**
 * Debt-token amortization ledger (tranche waterfall).
 * 
 * Rewritten by the fuzzing work. Every defect below was reachable from a
 * public entry point with attacker-chosen arguments, and none of them
 * reported itself as an error — they either trapped, which is
 * indistinguishable from a genuine bug, or silently corrupted the ledger.
 */
export namespace DebtToken {
  /**
   * Install the admin. Required before any ledger mutation, because `accrue_interest` and `trigger_default` are admin-gated and previously had no admin at all — anyone could inflate any tranche's debt.
   */
  export interface InitializeInput {
    admin: string;
  }
  export type InitializeOutput = void;

  /**
   * Apply `amount` to the waterfall, paying `Senior` first, then `Mezzanine`, then `Equity`.  Fixed here:  * a non-positive `amount` is rejected. It used to be accepted, and a   negative amount *increased* every tranche's owed balance, because each   tranche was credited `owed - payment` with `payment` itself negative; * each tranche's payment is now capped at that tranche's own owed   balance. The `Equity` leg previously took the entire uncapped   remainder, so repaying more than was outstanding underflowed   `equity_owed - equity_payment` and trapped; * `i128::MIN` is rejected up front, so no leg can compute   `owed - i128::MIN`.  Overpayment beyond the total outstanding is accepted and simply retires the whole ledger; the excess is not credited anywhere.
   */
  export interface DepositRepaymentInput {
    borrower: string;
    amount: bigint | string;
  }
  export type DepositRepaymentOutput = void;

  /**
   * Invokes `accrue_interest` on debt-token.
   */
  export interface AccrueInterestInput {
    tranche: any;
    amount: bigint | string;
  }
  export type AccrueInterestOutput = void;

  /**
   * Issue #85: set kinked-curve parameters (first caller becomes rate admin).
   */
  export interface SetRateParamsInput {
    admin: string;
    params: any;
  }
  export type SetRateParamsOutput = void;

  /**
   * Invokes `get_rate_params` on debt-token.
   */
  export interface GetRateParamsInput {
  }
  export type GetRateParamsOutput = any;

  /**
   * Annual borrow rate (WAD) for the given pool balances.
   */
  export interface CurrentBorrowRateInput {
    borrowed: bigint | string;
    available: bigint | string;
  }
  export type CurrentBorrowRateOutput = bigint | string;

  /**
   * Pool utilization (WAD).
   */
  export interface PoolUtilizationInput {
    borrowed: bigint | string;
    available: bigint | string;
  }
  export type PoolUtilizationOutput = bigint | string;

  /**
   * Accrue the WAD borrow index to the current ledger time; returns it.
   */
  export interface AccrueRateIndexInput {
    borrowed: bigint | string;
    available: bigint | string;
  }
  export type AccrueRateIndexOutput = bigint | string;

  /**
   * Invokes `trigger_default` on debt-token.
   */
  export interface TriggerDefaultInput {
  }
  export type TriggerDefaultOutput = void;

  export interface Client {
    readonly contractId: string;
    initialize(params: InitializeInput): Promise<InitializeOutput>;
    depositRepayment(params: DepositRepaymentInput): Promise<DepositRepaymentOutput>;
    accrueInterest(params: AccrueInterestInput): Promise<AccrueInterestOutput>;
    setRateParams(params: SetRateParamsInput): Promise<SetRateParamsOutput>;
    getRateParams(params: GetRateParamsInput): Promise<GetRateParamsOutput>;
    currentBorrowRate(params: CurrentBorrowRateInput): Promise<CurrentBorrowRateOutput>;
    poolUtilization(params: PoolUtilizationInput): Promise<PoolUtilizationOutput>;
    accrueRateIndex(params: AccrueRateIndexInput): Promise<AccrueRateIndexOutput>;
    triggerDefault(params: TriggerDefaultInput): Promise<TriggerDefaultOutput>;
  }
}

