// ----------------------------------------------------------------------------
// Contract: nft-deed
// ----------------------------------------------------------------------------

/**
 * NFT Property Deed & Legal Title Binding Contract.
 * 
 * Binds fractional ERC-20 style asset tokens to a single master NFT
 * representing the legal deed title stored in municipal land registries.
 * 
 * # Architecture
 * 
 * - The master NFT (token_id `0`) represents the legal deed title.
 * - While fractional tokens are actively trading, the master NFT is
 *   locked in a vault contract.
 * - To unlock and transfer the master NFT, 100% of the fractional tokens
 *   must be redeemed (burned) back to the asset-token contract.
 * - Once all tokens are redeemed, the NFT can be transferred to the
 *   redeemer, completing the legal title transfer.
 * 
 * # State machine
 * 
 * ```text
 * Locked ──100% redemption──► Unlocked ──transfer_nft──► Transferred
 * ```
 */
export namespace NftDeed {
  /**
   * Initialize the NFT deed contract.  - `admin`              — contract administrator. - `fractional_token`   — the fractional asset-token contract address. - `vault`              — the vault contract where the NFT is locked. - `deed_uri`           — URI of the legal deed document (e.g. IPFS). - `registry_id`        — municipal land registry identifier. - `beneficiary`        — the address that can claim the NFT upon full                          redemption of all fractional tokens.
   */
  export interface InitializeInput {
    admin: string;
    fractional_token: string;
    vault: string;
    deed_uri: string;
    registry_id: string;
    beneficiary: string;
  }
  export type InitializeOutput = void;

  /**
   * Returns the owner of the given token ID.  While the NFT is locked, the owner is the vault contract. After unlocking, the owner is the beneficiary who redeemed all tokens.
   */
  export interface OwnerOfInput {
    token_id: bigint | string;
  }
  export type OwnerOfOutput = string;

  /**
   * Transfer the master NFT to a new owner.  Can only be called when the NFT is unlocked (all fractional tokens have been redeemed). The caller must be the current owner.
   */
  export interface TransferNftInput {
    from: string;
    to: string;
    token_id: bigint | string;
  }
  export type TransferNftOutput = void;

  /**
   * Returns the metadata URI for the given token ID.  This URI points to the legal deed document stored in the municipal land registry (or an IPFS mirror of it).
   */
  export interface TokenUriInput {
    token_id: bigint | string;
  }
  export type TokenUriOutput = string;

  /**
   * Redeem fractional tokens to unlock the master NFT.  The caller specifies how many fractional tokens they are redeeming. Once the cumulative redeemed amount reaches 100% of the original total supply, the NFT is unlocked and can be transferred to the beneficiary.  This function: 1. Burns the specified amount of fractional tokens from the caller. 2. Tracks cumulative redemptions. 3. If 100% redeemed, unlocks the NFT and assigns ownership to the    beneficiary.
   */
  export interface RedeemAndUnlockInput {
    holder: string;
    amount: bigint | string;
  }
  export type RedeemAndUnlockOutput = void;

  /**
   * Check if the master NFT is unlocked (all fractional tokens redeemed).
   */
  export interface IsUnlockedInput {
  }
  export type IsUnlockedOutput = boolean;

  /**
   * Returns the bound fractional asset-token contract address.
   */
  export interface FractionalTokenInput {
  }
  export type FractionalTokenOutput = string;

  /**
   * Returns the vault contract address.
   */
  export interface VaultInput {
  }
  export type VaultOutput = string;

  /**
   * Returns the beneficiary address.
   */
  export interface BeneficiaryInput {
  }
  export type BeneficiaryOutput = string;

  /**
   * Returns the municipal land registry identifier.
   */
  export interface RegistryIdInput {
  }
  export type RegistryIdOutput = string;

  /**
   * Returns the original total supply of fractional tokens at binding time.
   */
  export interface FractionalTotalSupplyInput {
  }
  export type FractionalTotalSupplyOutput = bigint | string;

  /**
   * Returns the current total supply of fractional tokens.
   */
  export interface CurrentFractionalSupplyInput {
  }
  export type CurrentFractionalSupplyOutput = bigint | string;

  /**
   * Returns the contract admin.
   */
  export interface AdminInput {
  }
  export type AdminOutput = string;

  /**
   * Current contract ABI version, polled by the off-chain indexer.
   */
  export interface VersionInput {
    _env: any;
  }
  export type VersionOutput = bigint | string;

  /**
   * Invokes `initialize` on nft-deed.
   */
  export interface InitializeInput {
    total_supply: bigint | string;
  }
  export type InitializeOutput = void;

  /**
   * Invokes `total_supply` on nft-deed.
   */
  export interface TotalSupplyInput {
  }
  export type TotalSupplyOutput = bigint | string;

  /**
   * Invokes `burn` on nft-deed.
   */
  export interface BurnInput {
    from: string;
    amount: bigint | string;
  }
  export type BurnOutput = void;

  export interface Client {
    readonly contractId: string;
    initialize(params: InitializeInput): Promise<InitializeOutput>;
    ownerOf(params: OwnerOfInput): Promise<OwnerOfOutput>;
    transferNft(params: TransferNftInput): Promise<TransferNftOutput>;
    tokenUri(params: TokenUriInput): Promise<TokenUriOutput>;
    redeemAndUnlock(params: RedeemAndUnlockInput): Promise<RedeemAndUnlockOutput>;
    isUnlocked(params: IsUnlockedInput): Promise<IsUnlockedOutput>;
    fractionalToken(params: FractionalTokenInput): Promise<FractionalTokenOutput>;
    vault(params: VaultInput): Promise<VaultOutput>;
    beneficiary(params: BeneficiaryInput): Promise<BeneficiaryOutput>;
    registryId(params: RegistryIdInput): Promise<RegistryIdOutput>;
    fractionalTotalSupply(params: FractionalTotalSupplyInput): Promise<FractionalTotalSupplyOutput>;
    currentFractionalSupply(params: CurrentFractionalSupplyInput): Promise<CurrentFractionalSupplyOutput>;
    admin(params: AdminInput): Promise<AdminOutput>;
    version(params: VersionInput): Promise<VersionOutput>;
    initialize(params: InitializeInput): Promise<InitializeOutput>;
    totalSupply(params: TotalSupplyInput): Promise<TotalSupplyOutput>;
    burn(params: BurnInput): Promise<BurnOutput>;
  }
}

