// ----------------------------------------------------------------------------
// Contract: settlement
// ----------------------------------------------------------------------------

/**
 * Atomic multilateral batch settlement engine (issue #316).
 * 
 * Bilateral pairs in tokenized secondary markets are often illiquid. A
 * multilateral cross-trade lets N participants settle a ring of trades —
 * A pays B in a real-estate token, B pays C in a bond token, C pays A in
 * USDC — as one indivisible unit, so nobody delivers their leg without
 * receiving theirs.
 * 
 * The settlement contract never takes custody. Each leg is a direct
 * `token.transfer(from, to, amount)` invoked by this contract on the
 * sender's behalf, so every sender must authorize the batch (their auth
 * entry covers this contract's root invocation and the token transfer
 * sub-invocations it makes). All validation — graph shape, conservation,
 * balances, compliance — runs before the first transfer, and the transfers
 * themselves run inside the same Soroban invocation: any panic anywhere
 * (failed auth, an underfunded sender, a token refusing a transfer) aborts
 * the transaction and rolls back every leg already applied.
 * 
 * Tokens must be registered by the admin before they can appear in a batch,
 * either as *regulated* (bound to the compliance contract whose
 * `is_allowed(address) -> bool` gates every leg in that token) or explicitly
 * as *unregulated* (e.g. a USDC Stellar Asset Contract used as the cash leg).
 * An unregistered token fails closed.
 * 
 * Alongside the batch engine the contract also exposes T+0 DVP instructions
 * (issue #390): counterparties sign a `SettlementInstruction`, either may call
 * `settle` on its settlement ledger for atomic delivery-versus-payment,
 * `net_settle` clears many instructions through the minimum number of net
 * transfers, and the settlement guarantee fund compensates a counterparty when
 * a pre-flight check shows the other side cannot perform.
 */
export namespace Settlement {
  /**
   * Invokes `initialize` on settlement.
   */
  export interface InitializeInput {
    admin: string;
  }
  export type InitializeOutput = void;

  /**
   * Register `token` as tradeable in batches. `compliance` is the compliance contract that gates the token; `None` registers it as an unregulated settlement asset (a cash leg such as USDC).
   */
  export interface RegisterAssetInput {
    admin: string;
    token: string;
    compliance: any;
  }
  export type RegisterAssetOutput = void;

  /**
   * Invokes `deregister_asset` on settlement.
   */
  export interface DeregisterAssetInput {
    admin: string;
    token: string;
  }
  export type DeregisterAssetOutput = void;

  /**
   * Invokes `get_asset_policy` on settlement.
   */
  export interface GetAssetPolicyInput {
    token: string;
  }
  export type GetAssetPolicyOutput = any;

  /**
   * Validate and atomically execute a multilateral cross-trade.  Returns the batch id. See [`batch_settler`] for the full rule set; every rule is checked before the first transfer, and any failure — including one raised by a token during execution — reverts every leg.
   */
  export interface ExecuteMultilateralSettlementInput {
    trade_legs: any[];
  }
  export type ExecuteMultilateralSettlementOutput = bigint | string;

  /**
   * Run every pre-execution check on `trade_legs` without moving funds or requiring auth. Panics with the same error the real settlement would.
   */
  export interface ValidateSettlementInput {
    trade_legs: any[];
  }
  export type ValidateSettlementOutput = void;

  /**
   * Invokes `batch_count` on settlement.
   */
  export interface BatchCountInput {
  }
  export type BatchCountOutput = bigint | string;

  /**
   * Invokes `pause` on settlement.
   */
  export interface PauseInput {
    admin: string;
  }
  export type PauseOutput = void;

  /**
   * Invokes `unpause` on settlement.
   */
  export interface UnpauseInput {
    admin: string;
  }
  export type UnpauseOutput = void;

  /**
   * Invokes `upgrade` on settlement.
   */
  export interface UpgradeInput {
    admin: string;
    new_wasm_hash: Uint8Array | string;
  }
  export type UpgradeOutput = void;

  /**
   * Create a bilateral DVP instruction. Both counterparties must authorize the exact terms; either may settle it once `settlement_ledger` is reached.
   */
  export interface CreateInstructionInput {
    buyer: string;
    seller: string;
    asset: string;
    amount: bigint | string;
    payment_asset: string;
    payment_amount: bigint | string;
    settlement_ledger: number;
  }
  export type CreateInstructionOutput = number;

  /**
   * Invokes `get_instruction` on settlement.
   */
  export interface GetInstructionInput {
    instruction_id: number;
  }
  export type GetInstructionOutput = any;

  /**
   * Atomically deliver `asset` to the buyer and `payment_asset` to the seller. Either party may call this; both must authorize the transfers.
   */
  export interface SettleInput {
    instruction_id: number;
  }
  export type SettleOutput = void;

  /**
   * Clear a set of pending instructions against each other. Returns the number of transfers executed — the minimum for the net positions.
   */
  export interface NetSettleInput {
    instruction_ids: number[];
  }
  export type NetSettleOutput = number;

  /**
   * Invokes `last_net_transfer_count` on settlement.
   */
  export interface LastNetTransferCountInput {
  }
  export type LastNetTransferCountOutput = number;

  /**
   * Invokes `instruction_count` on settlement.
   */
  export interface InstructionCountInput {
  }
  export type InstructionCountOutput = number;

  /**
   * Set the per-token maximum guarantee payout (`0` disables coverage).
   */
  export interface ConfigureGuaranteeInput {
    admin: string;
    token: string;
    max_amount: bigint | string;
  }
  export type ConfigureGuaranteeOutput = void;

  /**
   * Deposit coverage collateral. Anyone may deposit; only the admin may withdraw, and only pending failures may pay out.
   */
  export interface DepositGuaranteeInput {
    depositor: string;
    token: string;
    amount: bigint | string;
  }
  export type DepositGuaranteeOutput = void;

  /**
   * Invokes `withdraw_guarantee` on settlement.
   */
  export interface WithdrawGuaranteeInput {
    admin: string;
    token: string;
    amount: bigint | string;
  }
  export type WithdrawGuaranteeOutput = void;

  /**
   * Invokes `guarantee_balance` on settlement.
   */
  export interface GuaranteeBalanceInput {
    token: string;
  }
  export type GuaranteeBalanceOutput = bigint | string;

  /**
   * Invokes `guarantee_cap` on settlement.
   */
  export interface GuaranteeCapInput {
    token: string;
  }
  export type GuaranteeCapOutput = bigint | string;

  export interface Client {
    readonly contractId: string;
    initialize(params: InitializeInput): Promise<InitializeOutput>;
    registerAsset(params: RegisterAssetInput): Promise<RegisterAssetOutput>;
    deregisterAsset(params: DeregisterAssetInput): Promise<DeregisterAssetOutput>;
    getAssetPolicy(params: GetAssetPolicyInput): Promise<GetAssetPolicyOutput>;
    executeMultilateralSettlement(params: ExecuteMultilateralSettlementInput): Promise<ExecuteMultilateralSettlementOutput>;
    validateSettlement(params: ValidateSettlementInput): Promise<ValidateSettlementOutput>;
    batchCount(params: BatchCountInput): Promise<BatchCountOutput>;
    pause(params: PauseInput): Promise<PauseOutput>;
    unpause(params: UnpauseInput): Promise<UnpauseOutput>;
    upgrade(params: UpgradeInput): Promise<UpgradeOutput>;
    createInstruction(params: CreateInstructionInput): Promise<CreateInstructionOutput>;
    getInstruction(params: GetInstructionInput): Promise<GetInstructionOutput>;
    settle(params: SettleInput): Promise<SettleOutput>;
    netSettle(params: NetSettleInput): Promise<NetSettleOutput>;
    lastNetTransferCount(params: LastNetTransferCountInput): Promise<LastNetTransferCountOutput>;
    instructionCount(params: InstructionCountInput): Promise<InstructionCountOutput>;
    configureGuarantee(params: ConfigureGuaranteeInput): Promise<ConfigureGuaranteeOutput>;
    depositGuarantee(params: DepositGuaranteeInput): Promise<DepositGuaranteeOutput>;
    withdrawGuarantee(params: WithdrawGuaranteeInput): Promise<WithdrawGuaranteeOutput>;
    guaranteeBalance(params: GuaranteeBalanceInput): Promise<GuaranteeBalanceOutput>;
    guaranteeCap(params: GuaranteeCapInput): Promise<GuaranteeCapOutput>;
  }
}

// ----------------------------------------------------------------------------
// Contract: state-channel
// ----------------------------------------------------------------------------

/**
 * Issue #322 - Off-Chain Layer-2 State Channel Framework for High-Frequency Rental Micropayments
 * 
 * Implements a bidirectional payment channel with the following guarantees:
 * - On-chain channel opening with locked escrow stakes from both parties
 * - Off-chain state exchange with Ed25519 signatures and monotonic sequence numbers
 * - Cooperative channel closure for optimal gas efficiency
 * - Unilateral dispute mechanism with 24-hour challenge window
 * - Slashing for dishonest counterparty submitting outdated state
 * 
 * Flow:
 * 1. Both parties call `open_channel` to lock escrow stakes on-chain
 * 2. Parties exchange signed state updates off-chain (handled by channel-node daemon)
 * 3. Either party calls `close_channel` cooperatively with final signed state
 * 4. If one party is unresponsive, initiate_dispute with latest signed state
 * 5. During 24h challenge window, counterparty can submit newer state via `challenge_dispute`
 * 6. After challenge window, call `finalize_dispute` to settle and slash if fraud detected
 * 
 * Issue #366 - dispute resolution with fraud proofs and adjudication timeout:
 * 1. Each party registers its Ed25519 signing key (`register_signing_key`)
 * 2. `open_dispute(channel_id, latest_state, signatures)` - either party submits
 *    a state signed by both parties; starts a `dispute_window_ledgers` window
 * 3. `counter_dispute(channel_id, newer_state, signatures)` - the counter-party
 *    submits a state with a higher sequence number within the window
 * 4. `submit_fraud_proof(channel_id, invalid_state, proof)` - anyone except the
 *    submitter proves a submitted state invalid (balance sum mismatch or a
 *    negative balance) and earns `fraud_bounty_bps` of the submitter's deposit
 * 5. `resolve_dispute(channel_id)` - after the window, closes the channel and
 *    settles at the highest-sequence valid state
 * 
 * Every submitted state's signatures are batch-verified (all-or-nothing).
 */
export namespace StateChannel {
  /**
   * Open a new payment channel. Both parties must call this to fund their stakes. channel_id is a unique identifier (e.g., hash of (party_a, party_b, nonce))
   */
  export interface OpenChannelInput {
    channel_id: Uint8Array | string;
    party_a: string;
    party_b: string;
    token: string;
    stake_a: bigint | string;
    stake_b: bigint | string;
    caller: string;
  }
  export type OpenChannelOutput = void;

  /**
   * Cooperatively close the channel with mutually signed final state. This is the gas-optimal path and settles immediately without disputes.
   */
  export interface CloseChannelInput {
    channel_id: Uint8Array | string;
    final_state: any;
    caller: string;
  }
  export type CloseChannelOutput = void;

  /**
   * Initiate unilateral dispute with the latest state you have. Starts a 24-hour challenge window for the counterparty to submit a newer state.
   */
  export interface InitiateDisputeInput {
    channel_id: Uint8Array | string;
    state: any;
    caller: string;
  }
  export type InitiateDisputeOutput = void;

  /**
   * Challenge a dispute by submitting a state with a higher sequence number. If successful, the challenger proves the dispute initiator submitted stale state (fraud).
   */
  export interface ChallengeDisputeInput {
    channel_id: Uint8Array | string;
    newer_state: any;
    caller: string;
  }
  export type ChallengeDisputeOutput = void;

  /**
   * Finalize the dispute after the challenge window expires. Settles balances according to the latest submitted state. If fraud was detected (challenge succeeded), slashes the dishonest party's escrow stake.
   */
  export interface FinalizeDisputeInput {
    channel_id: Uint8Array | string;
    caller: string;
  }
  export type FinalizeDisputeOutput = void;

  /**
   * One-time setup of the adjudication parameters. Until this is called the contract uses `DISPUTE_WINDOW_LEDGERS` and `DEFAULT_FRAUD_BOUNTY_BPS`.
   */
  export interface InitDisputeConfigInput {
    admin: string;
    dispute_window_ledgers: number;
    fraud_bounty_bps: number;
  }
  export type InitDisputeConfigOutput = void;

  /**
   * Admin-only update of the adjudication parameters. Disputes that are already open keep the window and bounty they were opened with.
   */
  export interface UpdateDisputeConfigInput {
    dispute_window_ledgers: number;
    fraud_bounty_bps: number;
  }
  export type UpdateDisputeConfigOutput = void;

  /**
   * Invokes `get_dispute_config` on state-channel.
   */
  export interface GetDisputeConfigInput {
  }
  export type GetDisputeConfigOutput = any;

  /**
   * Register the Ed25519 key `party` signs channel states with. Each key can be set once, before any dispute is opened, so a party cannot swap keys to repudiate states it already signed.
   */
  export interface RegisterSigningKeyInput {
    channel_id: Uint8Array | string;
    party: string;
    public_key: Uint8Array | string;
  }
  export type RegisterSigningKeyOutput = void;

  /**
   * Invokes `get_signing_keys` on state-channel.
   */
  export interface GetSigningKeysInput {
    channel_id: Uint8Array | string;
  }
  export type GetSigningKeysOutput = any;

  /**
   * Invokes `get_dispute` on state-channel.
   */
  export interface GetDisputeInput {
    channel_id: Uint8Array | string;
  }
  export type GetDisputeOutput = any;

  /**
   * (1) Open a dispute with the latest state `caller` holds.  `signatures` must be `[sig_a, sig_b]` over the state and is batch-verified against the registered keys. The state's balances are deliberately *not* checked here (optimistic adjudication): an invalid state can be disproven by anyone through `submit_fraud_proof`, and `resolve_dispute` never settles at an invalid state.
   */
  export interface OpenDisputeInput {
    channel_id: Uint8Array | string;
    latest_state: any;
    signatures: Uint8Array | string[];
    caller: string;
  }
  export type OpenDisputeOutput = void;

  /**
   * (2) The counter-party answers an open dispute with a newer state.  Only accepted within the dispute window and only if `newer_state` has a strictly higher sequence than every submission not yet proven fraudulent.
   */
  export interface CounterDisputeInput {
    channel_id: Uint8Array | string;
    newer_state: any;
    signatures: Uint8Array | string[];
    caller: string;
  }
  export type CounterDisputeOutput = void;

  /**
   * Fraud proof: anyone other than the submitter can show that a submitted state is provably invalid and earn `fraud_bounty_bps` of the submitter's deposit. The disproven state is excluded from settlement.  The bounty is capped at what remains of the submitter's deposit, and is accounted for at settlement, so it can never be paid from the counter-party's funds or from other channels.
   */
  export interface SubmitFraudProofInput {
    channel_id: Uint8Array | string;
    invalid_state: any;
    proof: any;
    prover: string;
  }
  export type SubmitFraudProofOutput = bigint | string;

  /**
   * (3) After the dispute window, close the channel and settle at the highest-sequence valid submission. If no valid submission exists the original deposits are returned. Fraud bounties already paid are deducted from the fraudulent party's share. Permissionless.
   */
  export interface ResolveDisputeInput {
    channel_id: Uint8Array | string;
  }
  export type ResolveDisputeOutput = any;

  /**
   * Get channel info
   */
  export interface GetChannelInput {
    channel_id: Uint8Array | string;
  }
  export type GetChannelOutput = any;

  export interface Client {
    readonly contractId: string;
    openChannel(params: OpenChannelInput): Promise<OpenChannelOutput>;
    closeChannel(params: CloseChannelInput): Promise<CloseChannelOutput>;
    initiateDispute(params: InitiateDisputeInput): Promise<InitiateDisputeOutput>;
    challengeDispute(params: ChallengeDisputeInput): Promise<ChallengeDisputeOutput>;
    finalizeDispute(params: FinalizeDisputeInput): Promise<FinalizeDisputeOutput>;
    initDisputeConfig(params: InitDisputeConfigInput): Promise<InitDisputeConfigOutput>;
    updateDisputeConfig(params: UpdateDisputeConfigInput): Promise<UpdateDisputeConfigOutput>;
    getDisputeConfig(params: GetDisputeConfigInput): Promise<GetDisputeConfigOutput>;
    registerSigningKey(params: RegisterSigningKeyInput): Promise<RegisterSigningKeyOutput>;
    getSigningKeys(params: GetSigningKeysInput): Promise<GetSigningKeysOutput>;
    getDispute(params: GetDisputeInput): Promise<GetDisputeOutput>;
    openDispute(params: OpenDisputeInput): Promise<OpenDisputeOutput>;
    counterDispute(params: CounterDisputeInput): Promise<CounterDisputeOutput>;
    submitFraudProof(params: SubmitFraudProofInput): Promise<SubmitFraudProofOutput>;
    resolveDispute(params: ResolveDisputeInput): Promise<ResolveDisputeOutput>;
    getChannel(params: GetChannelInput): Promise<GetChannelOutput>;
  }
}

