// ----------------------------------------------------------------------------
// Contract: vesting
// ----------------------------------------------------------------------------

/**
 * Token vesting schedules with configurable cliffs and linear vesting.
 */
export namespace Vesting {
  /**
   * Initialize the vesting contract with its funding token and refund treasury.
   */
  export interface InitializeInput {
    admin: string;
    token: string;
    treasury: string;
  }
  export type InitializeOutput = void;

  /**
   * Create and fund a schedule. `start_time` and durations are ledger timestamp seconds. At the cliff, the beneficiary may claim the linear amount accrued since `start_time`.
   */
  export interface CreateVestingScheduleInput {
    admin: string;
    beneficiary: string;
    start_time: bigint | string;
    cliff_duration: bigint | string;
    total_duration: bigint | string;
    amount: bigint | string;
    revocable: boolean;
  }
  export type CreateVestingScheduleOutput = bigint | string;

  /**
   * Claim all currently vested but previously unclaimed tokens for one schedule. #388: guarded against reentrancy via a TemporaryStorage mutex flag.
   */
  export interface ClaimVestedTokensInput {
    beneficiary: string;
    schedule_id: bigint | string;
  }
  export type ClaimVestedTokensOutput = bigint | string;

  /**
   * #388: Slash unvested tokens by `bps` basis points (100 = 1%). Slashed tokens are transferred to the governance treasury, not destroyed. `reason_hash` is a governance proposal ID for auditability.
   */
  export interface SlashInput {
    admin: string;
    schedule_id: bigint | string;
    reason_hash: any;
    bps: number;
  }
  export type SlashOutput = bigint | string;

  /**
   * Revoke an active schedule and return its unvested balance to the treasury. Any vested amount remains claimable by the beneficiary.
   */
  export interface RevokeVestingScheduleInput {
    admin: string;
    schedule_id: bigint | string;
  }
  export type RevokeVestingScheduleOutput = bigint | string;

  /**
   * Invokes `get_vesting_schedule` on vesting.
   */
  export interface GetVestingScheduleInput {
    schedule_id: bigint | string;
  }
  export type GetVestingScheduleOutput = any;

  /**
   * Invokes `version` on vesting.
   */
  export interface VersionInput {
    _env: any;
  }
  export type VersionOutput = bigint | string;

  export interface Client {
    readonly contractId: string;
    initialize(params: InitializeInput): Promise<InitializeOutput>;
    createVestingSchedule(params: CreateVestingScheduleInput): Promise<CreateVestingScheduleOutput>;
    claimVestedTokens(params: ClaimVestedTokensInput): Promise<ClaimVestedTokensOutput>;
    slash(params: SlashInput): Promise<SlashOutput>;
    revokeVestingSchedule(params: RevokeVestingScheduleInput): Promise<RevokeVestingScheduleOutput>;
    getVestingSchedule(params: GetVestingScheduleInput): Promise<GetVestingScheduleOutput>;
    version(params: VersionInput): Promise<VersionOutput>;
  }
}

